export const normalized=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function searchRooms(rows,params){const q=normalized(params.get('q')||'').trim();let asepsis=params.get('asepsis')||'',material=params.get('material')||'',pending=params.get('pending')==='true',geometry=params.get('geometry')==='true',natural=false;const doc=params.get('document');const codes=[...new Set(rows.filter(r=>{const c=normalized(r.code),i=q.indexOf(c);return i>=0&&!/[a-z0-9.-]/.test(q[i+c.length]||' ');}).map(r=>r.code))];if(q.includes('asepsia')){asepsis=['baja','media','alta'].find(x=>q.includes(x))||asepsis;natural=!!asepsis;}if(q.includes('porcelanato')){material='porcelanato';natural=true;}if(['incompleta','pendiente','sin informacion'].some(x=>q.includes(x))){pending=true;natural=true;}const m=q.match(/(?:cielo|pavimento|pintura|terminacion|material)\s+(?:codigo\s+)?(\d{2,3})\b/);if(m){material=m[1];natural=true;}
// Atajos por campo de la monografía: «pav 109», «cie 202», «muro 14», «m2 14».
const s=q.match(/^(pav|pavimento|cie|cielo|muro|m[1-4]?)\s*[-:]?\s*(\d{2,3})$/),field=s?(s[1].startsWith('p')?'PAV':s[1].startsWith('c')?'CIE':/^m[1-4]$/.test(s[1])?s[1].toUpperCase():'M'):null;if(s){material='';natural=true;}
return rows.filter(r=>(!doc||r.document_id===doc)&&(!field||r.finishes.some(f=>(field==='M'?/^M[1-4]$/.test(f.field):f.field===field)&&f.code===s[2]))&&(!asepsis||r.asepsis.includes(asepsis))&&(!pending||r.status!=='Validado')&&(!geometry||r.polygon||r.has_polygon)&&(!material||r.finishes.some(f=>normalized(f.code+' '+f.description).includes(normalized(material))))&&(codes.length?codes.includes(r.code):!q||natural||normalized(r.code+' '+r.name).includes(q)||r.finishes.some(f=>q===f.code||normalized(f.description).includes(q))));}
export function inside(p,ring){let c=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])c=!c;}return c;}
const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
export function intersects(a,b,c,d){return cross(a,b,c)*cross(a,b,d)<-1e-6&&cross(c,d,a)*cross(c,d,b)<-1e-6;}
export function validatePolygon(pts,w,h){if(!Array.isArray(pts)||pts.length<3||pts.length>5000)throw Error('Define entre 3 y 5000 vértices.');if(pts.some(p=>!Array.isArray(p)||p.length!==2||p.some(v=>!Number.isFinite(v))||p[0]<0||p[1]<0||p[0]>w||p[1]>h))throw Error('El contorno sale de la lámina o tiene coordenadas inválidas.');let area=0;for(let i=0;i<pts.length;i++){const a=pts[i],b=pts[(i+1)%pts.length];area+=a[0]*b[1]-b[0]*a[1];for(let j=i+2;j<pts.length;j++){if(i===0&&j===pts.length-1)continue;if(intersects(a,b,pts[j],pts[(j+1)%pts.length]))throw Error('El contorno tiene líneas cruzadas.');}}if(Math.abs(area)<2)throw Error('El contorno no tiene área válida.');return true;}
